"""mpl_toolkits.axisartist.axislines — axes with custom axis lines."""

from matplotlib.axes._axes import Axes as _Axes


class Axes(_Axes):
    name = 'axisartist.Axes'
    class AxisDict(dict):
        def __init__(self, axes):
            super().__init__()
            self._axes = axes

class SubplotZero(Axes):
    name = 'axisartist.SubplotZero'

class Subplot(Axes):
    pass

class AxesZero(SubplotZero):
    pass


# ─── Added: missing axislines helper classes ────────────────────────


class GridHelperBase:
    """Base for grid-line / tick-position helpers. Subclasses override
    ``update_lim`` to recompute their cached state when axis limits
    change."""

    def __init__(self):
        self._invalidate = True

    def invalidate(self):    self._invalidate = True
    def get_grid_info(self, *args, **kwargs): return None
    def update_lim(self, axes):  self._invalidate = False


class GridHelperRectlinear(GridHelperBase):
    """Grid helper for plain rectilinear axes. Returns evenly-spaced
    gridlines computed from the axis limits."""

    def __init__(self, axes=None):
        super().__init__()
        self.axes = axes


class AxisArtistHelper:
    """Configurable axis-artist helper — base class. Subclasses pick
    the axis location (left/right/top/bottom) and tick direction."""

    def __init__(self, axes, loc, nth_coord=None):
        self.axes = axes
        self._loc = loc
        self.nth_coord = nth_coord

    class _Base:
        """Inner namespace for shared helper logic."""
        pass


class AxisArtistHelperRectlinear(AxisArtistHelper):
    """Axis artist helper for rectilinear (non-curvilinear) axes."""
    pass


class FixedAxisArtistHelperRectilinear(AxisArtistHelperRectlinear):
    """Axis artist fixed at a particular edge (left/right/top/bottom)."""

    def __init__(self, axes, loc, nth_coord=None):
        super().__init__(axes, loc, nth_coord)


class FloatingAxisArtistHelperRectilinear(AxisArtistHelperRectlinear):
    """Axis artist that floats at a data value rather than being pinned
    to an edge."""

    def __init__(self, axes, nth_coord, value, axis_direction='bottom'):
        super().__init__(axes, axis_direction, nth_coord)
        self.value = value
